// Generated by /ship test coverage audit (pass 1).
// Value: protects=Export all never resets the export reminder when the open draft still has unsaved words, and says so in its label;
//   fails_when=the writer.dirty check is dropped or onExported runs before/regardless of it; import errors stop showing the backup message;
//   why_new=settings.test.ts covers importLabel only; nothing exercises exportAll/importBackup branches; seam=none;
//   no_claim=a real browser download or file picker (platform download/pickFile mocked; storage and writer are fakes; unit only)
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { BackupError, encodeBackup } from '../core/backup';
import { newDraft } from '../core/draft';
import type { BackupData, StorageAdapter } from '../core/storage';
import type { DraftWriter } from '../storage/writer';

const platform = vi.hoisted(() => ({ download: vi.fn(), pickFile: vi.fn() }));
vi.mock('./platform', () => platform);

const { exportAll, importBackup } = await import('./backupActions');

const data: BackupData = {
  format: 'kansobackup',
  v: 1,
  exportedAt: 1,
  drafts: [{ record: newDraft('a', 1), ops: [], snapshots: [] }],
  days: [],
};
const storageWith = (over: Partial<StorageAdapter> = {}) => ({ exportAll: async () => data, ...over }) as unknown as StorageAdapter;
const writer = (dirtyAfterFlush: boolean) => {
  const w = { dirty: true, flush: vi.fn(async () => void (w.dirty = dirtyAfterFlush)) };
  return w as unknown as DraftWriter & { flush: ReturnType<typeof vi.fn> };
};

beforeEach(() => {
  platform.download.mockReset();
  platform.pickFile.mockReset();
});

describe('exportAll (R21, 9A feedback)', () => {
  it('flushes the open word first and resets the reminder when everything is saved', async () => {
    const onExported = vi.fn();
    const w = writer(false);
    const label = await exportAll(storageWith(), onExported, w);
    expect(w.flush).toHaveBeenCalledWith(true);
    expect(platform.download).toHaveBeenCalledTimes(1);
    expect(platform.download.mock.calls[0]![0]).toMatch(/^kansowriter-\d{4}-\d{2}-\d{2}\.kansobackup$/);
    expect(onExported).toHaveBeenCalledTimes(1);
    expect(label).toBe(`Saved ${platform.download.mock.calls[0]![0]}`);
  });

  it('still writes the file but does NOT reset the reminder when words are still unsaved', async () => {
    const onExported = vi.fn();
    const label = await exportAll(storageWith(), onExported, writer(true));
    expect(platform.download).toHaveBeenCalledTimes(1);
    expect(onExported).not.toHaveBeenCalled();
    expect(label).toMatch(/without your newest unsaved words$/);
  });

  it('shows the BackupError text, and a retry hint when the browser blocks the download', async () => {
    const onExported = vi.fn();
    const tooBig = storageWith({ exportAll: async () => Promise.reject(new BackupError('Your drafts are too large for one backup file')) });
    expect(await exportAll(tooBig, onExported)).toBe('Your drafts are too large for one backup file');
    platform.download.mockImplementation(() => {
      throw new Error('blocked');
    });
    expect(await exportAll(storageWith(), onExported)).toBe('Your browser blocked the download. Try again');
    expect(onExported).not.toHaveBeenCalled();
  });
});

describe('importBackup', () => {
  const file = (bytes: Uint8Array) => ({ arrayBuffer: async () => bytes.slice().buffer }) as unknown as File;

  it('a cancelled picker does nothing', async () => {
    platform.pickFile.mockResolvedValue(null);
    const importAll = vi.fn();
    expect(await importBackup(storageWith({ importAll }))).toBeNull();
    expect(importAll).not.toHaveBeenCalled();
  });

  it('a file that is not a backup reports it and imports nothing', async () => {
    platform.pickFile.mockResolvedValue(file(new TextEncoder().encode('just some notes')));
    const importAll = vi.fn();
    expect(await importBackup(storageWith({ importAll }))).toEqual({ label: 'That file isn’t a Kansowriter backup', added: 0 });
    expect(importAll).not.toHaveBeenCalled();
  });

  it('a valid backup is imported and labelled from the result', async () => {
    platform.pickFile.mockResolvedValue(file(await encodeBackup(data)));
    const importAll = vi.fn(async () => ({ added: 1, copies: 0, skipped: 0, damaged: 0 }));
    expect(await importBackup(storageWith({ importAll }))).toEqual({ label: 'Added 1 draft', added: 1 });
    expect(importAll).toHaveBeenCalledWith(
      expect.objectContaining({ format: 'kansobackup', drafts: [expect.objectContaining({ ops: [] })] }),
    );
  });

  // Regression: a valid backup that fails to store was reported as "That file isn’t a Kansowriter backup"
  // Found by the /ship coverage audit on 2026-10-24
  // Value: protects=a storage failure while restoring a valid backup says the device's storage failed, not that the file is wrong;
  //   fails_when=importAll errors fall back into the not-a-backup label again; seam=none;
  //   no_claim=a real quota error (importAll rejects in a fake)
  it('a storage failure during import blames storage, not the file, instead of throwing', async () => {
    platform.pickFile.mockResolvedValue(file(await encodeBackup(data)));
    const importAll = vi.fn(async () => Promise.reject(new DOMException('full', 'QuotaExceededError')));
    expect(await importBackup(storageWith({ importAll }))).toEqual({
      label: 'Couldn’t restore: this device’s storage is full or unavailable',
      added: 0,
    });
  });
});
